import { Pool } from "pg";

export interface Probe {
  name: string;
  check(): Promise<void>;
}

function withTimeout<T>(p: Promise<T>, ms: number, label: string): Promise<T> {
  let timer: NodeJS.Timeout;
  return Promise.race([
    p,
    new Promise<T>((_, reject) => {
      timer = setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms);
    }),
  ]).finally(() => clearTimeout(timer));
}

export function postgresProbe(pool: Pool, timeoutMs: number): Probe {
  return {
    name: "postgres",
    check: async () => {
      await withTimeout(pool.query("SELECT 1"), timeoutMs, "postgres");
    },
  };
}

export function ehrGatewayProbe(baseUrl: string, timeoutMs: number): Probe {
  return {
    name: "ehr_gateway",
    check: async () => {
      const res = await fetch(`${baseUrl}/status`, { signal: AbortSignal.timeout(timeoutMs) });
      if (!res.ok) {
        throw new Error(`ehr_gateway returned ${res.status}`);
      }
    },
  };
}

import { Router, Request, Response } from "express";
import { Probe } from "./dependencies";

interface ProbeOutcome {
  name: string;
  ok: boolean;
  error?: string;
}

async function runAll(probes: Probe[]): Promise<ProbeOutcome[]> {
  const settled = await Promise.allSettled(probes.map((p) => p.check()));
  return settled.map((s, i) => ({
    name: probes[i].name,
    ok: s.status === "fulfilled",
    error: s.status === "rejected" ? String((s.reason as Error)?.message ?? s.reason) : undefined,
  }));
}

export interface HealthState {
  startedAt: number;
  migrationsApplied: boolean;
  draining: boolean;
}

export function healthRouter(state: HealthState, probes: Probe[], log: (o: object) => void): Router {
  const router = Router();

  router.get("/health/live", async (_req: Request, res: Response) => {
    const outcomes = await runAll(probes.filter((p) => p.name === "postgres"));
    const ok = outcomes.every((o) => o.ok);
    if (!ok) {
      log({ msg: "liveness failing", outcomes });
    }
    res.status(ok ? 200 : 503).json({ status: ok ? "alive" : "dead", uptimeMs: Date.now() - state.startedAt });
  });

  router.get("/health/ready", async (_req: Request, res: Response) => {
    if (state.draining || !state.migrationsApplied) {
      res.status(503).json({ status: state.draining ? "draining" : "starting" });
      return;
    }

    const outcomes = await runAll(probes);
    const ok = outcomes.every((o) => o.ok);
    if (!ok) {
      log({ msg: "readiness failing", outcomes });
    }
    res.set("Cache-Control", "no-store");
    res.status(ok ? 200 : 503).json({ status: ok ? "ready" : "not_ready", checks: outcomes });
  });

  return router;
}

import express from "express";
import { Pool } from "pg";
import { ehrGatewayProbe, postgresProbe } from "./dependencies";
import { healthRouter, HealthState } from "./healthRoutes";

export async function startSchedulingApi(port: number): Promise<void> {
  const pool = new Pool({ connectionString: process.env.DATABASE_URL, max: 20 });
  const state: HealthState = { startedAt: Date.now(), migrationsApplied: false, draining: false };
  const log = (o: object) => console.log(JSON.stringify({ svc: "appointments", ...o }));

  const probes = [
    postgresProbe(pool, 1_000),
    ehrGatewayProbe(process.env.EHR_GATEWAY_URL ?? "http://ehr-gateway:8080", 1_500),
  ];

  const app = express();
  app.use(healthRouter(state, probes, log));

  const server = app.listen(port, () => log({ msg: "listening", port }));

  await pool.query("SELECT pg_advisory_lock(42)");
  try {
    await pool.query("CREATE TABLE IF NOT EXISTS appointments (id uuid PRIMARY KEY, patient_id uuid NOT NULL, slot_start timestamptz NOT NULL)");
  } finally {
    await pool.query("SELECT pg_advisory_unlock(42)");
  }
  state.migrationsApplied = true;

  process.once("SIGTERM", () => {
    state.draining = true;
    setTimeout(() => {
      server.close(() => pool.end().finally(() => process.exit(0)));
    }, 10_000);
  });
}
